package wayland_test

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/egdaemon/eg/runtime/wasi/eg"
	"github.com/egdaemon/eg/runtime/x/wasi/wayland"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestBackport(t *testing.T) {
	t.Run("returns a non-nil OpFn", func(t *testing.T) {
		fn := wayland.Backport()
		require.NotNil(t, fn)
	})

	t.Run("skips when wayland socket file exists", func(t *testing.T) {
		sock := filepath.Join(t.TempDir(), "wayland.sock")
		require.NoError(t, os.WriteFile(sock, nil, 0o644))
		t.Setenv("WAYLAND_DISPLAY", sock)

		err := eg.Perform(t.Context(), wayland.Backport())
		require.NoError(t, err)
	})
}
